import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"LocalSend Settings","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/localsend.md","filePath":"user-guide/settings/localsend.md","lastUpdated":1785993908000}'),r={name:"user-guide/settings/localsend.md"};function i(s,e,l,d,c,g){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="localsend-settings" tabindex="-1">LocalSend Settings <a class="header-anchor" href="#localsend-settings" aria-label="Permalink to &quot;LocalSend Settings&quot;">​</a></h1><p>Lertaro includes built-in compatibility with the official <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> protocol for local network cross-device transfers, enabling fast file, folder, and plain text sharing between mobile and desktop devices on the same LAN. Located at <strong>Settings → LocalSend</strong>.</p><h2 id="basic-settings" tabindex="-1">Basic Settings <a class="header-anchor" href="#basic-settings" aria-label="Permalink to &quot;Basic Settings&quot;">​</a></h2><ul><li><strong>Enable LocalSend Transfer</strong> —— Toggles the LocalSend service on or off. When enabled, the tray menu provides a &quot;Send via LocalSend...&quot; option and responds to the global hotkey.</li><li><strong>Device Alias</strong> —— Alias displayed when recognized by other LocalSend clients on the LAN. Automatically generated from host system name by default.</li><li><strong>Port</strong> —— HTTP/HTTPS port for listening to incoming transfer requests (default <code>53317</code>).</li></ul><h2 id="security-encryption" tabindex="-1">Security &amp; Encryption <a class="header-anchor" href="#security-encryption" aria-label="Permalink to &quot;Security &amp; Encryption&quot;">​</a></h2><ul><li><strong>Encrypted Transfer (HTTPS)</strong> —— Uses HTTPS encrypted connection for data transfer when enabled (requires target device HTTPS support).</li><li><strong>Receive PIN</strong> —— Optional PIN code required for incoming transfer authorization (leave blank to disable).</li></ul><h2 id="receiving-storage" tabindex="-1">Receiving &amp; Storage <a class="header-anchor" href="#receiving-storage" aria-label="Permalink to &quot;Receiving &amp; Storage&quot;">​</a></h2><ul><li><strong>Quick Save (Auto Save)</strong> —— Automatically accepts and saves incoming files from trusted clients without requiring manual confirmation.</li><li><strong>Download Location</strong> —— Default destination directory for received files.</li></ul><h2 id="summon-transfer-modes" tabindex="-1">Summon &amp; Transfer Modes <a class="header-anchor" href="#summon-transfer-modes" aria-label="Permalink to &quot;Summon &amp; Transfer Modes&quot;">​</a></h2><ul><li><strong>Hotkey Summon</strong> —— Press <strong><code>Ctrl+S</code></strong> by default (configurable in <a href="./hotkeys-page.html">Hotkeys Settings</a>) or select &quot;Send via LocalSend...&quot; in tray menu.</li><li><strong>Mode Switching</strong> —— Send window supports switching between [ Send Files / Folders ] and [ Send Text ] modes, as well as drag-and-drop file addition directly from search results.</li></ul>',10)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
